#include "services/user_repository.hpp"

#include <algorithm>
#include <cctype>

namespace cms::services {

std::string UserRepository::NormalizeEmail(const std::string& email) {
  std::string lowered = email;
  std::transform(lowered.begin(), lowered.end(), lowered.begin(),
                 [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
  return lowered;
}

bool UserRepository::EmailExists(const std::string& email) const {
  return by_email_.contains(NormalizeEmail(email));
}

