  if (manuscript_file_size_bytes == 0 || manuscript_file_size_bytes > kMaxManuscriptBytes) {
    return {SubmitPaperStatus::kFileTooLarge, "manuscript exceeds 10 MB limit", 0};
  }

  for (auto& paper : papers_) {
