    10	bool RegistrationService::IsValidAttendanceType(const std::string& attendance_type) {
    11	  if (cms::lib::IsBlank(attendance_type)) {
    12	    return false;
    13	  }
    14	  std::string normalized = attendance_type;
    15	  std::transform(normalized.begin(), normalized.end(), normalized.begin(),
    16	                 [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    17	  return normalized == "student" || normalized == "regular" || normalized == "vip";
    18	}
