    14	bool PaymentService::IsValidPaymentInfo(const PaymentRequest& request) {
    15	  if (request.card_number.size() != 16 || request.cvv.size() != 3 || request.expiry.size() != 5) {
    16	    return false;
    17	  }
    18	  if (request.expiry[2] != '/') {
    19	    return false;
    20	  }
    21	  return IsAllDigits(request.card_number) && IsAllDigits(request.cvv) &&
    22	         IsAllDigits(request.expiry.substr(0, 2)) && IsAllDigits(request.expiry.substr(3, 2));
    23	}
