    25	PaymentResult PaymentService::ProcessPayment(int registration_id, const PaymentRequest& request) {
    26	  auto registration = registration_service_->FindById(registration_id);
    27	  if (!registration.has_value()) {
    28	    return {PaymentStatus::kRegistrationNotFound, "registration not found", 0, 0};
    29	  }
    30	  if (registration->status == cms::models::RegistrationStatus::kPaid) {
    31	    return {PaymentStatus::kDuplicatePayment, "duplicate payment blocked", 0, 0};
    32	  }
    33	  if (!IsValidPaymentInfo(request)) {
    34	    return {PaymentStatus::kInvalidPaymentInfo, "invalid payment information", 0, 0};
    35	  }
    36	  if (request.simulate_decline) {
    37	    registration_service_->MarkRegistrationFailed(registration_id);
    38	    payments_.push_back(
    39	        {next_payment_id_++, registration_id, "failed"});
    40	    return {PaymentStatus::kDeclined, "payment declined", 0, 0};
    41	  }
    42	  if (request.simulate_record_failure) {
    43	    return {PaymentStatus::kSystemError, "registration could not be completed", 0, 0};
    44	  }
    45	
    46	  cms::models::PaymentRecord payment{next_payment_id_++, registration_id, "succeeded"};
    47	  payments_.push_back(payment);
    48	  registration_service_->MarkRegistrationPaid(registration_id);
    49	
    50	  cms::models::Ticket ticket{next_ticket_id_++, registration_id,
    51	                             "TICKET-" + std::to_string(registration_id) + "-" +
    52	                                 std::to_string(next_ticket_id_)};
    53	  tickets_.push_back(ticket);
    54	
    55	  ++confirmation_count_;
    56	  last_confirmation_message_ = "Registration confirmed for id=" + std::to_string(registration_id);
    57	  return {PaymentStatus::kPaid, "payment processed", payment.id, ticket.id};
    58	}
